dashboard.definition:
{
    "title": "Network Intelligence",
    "description": "Cisco Network Intelligence: Catalyst Center and Meraki",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        },
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": [
                    {
                        "label": "All sites",
                        "value": "*"
                    },
                    {
                        "label": "Atlanta",
                        "value": "atlanta"
                    },
                    {
                        "label": "Berlin",
                        "value": "berlin"
                    },
                    {
                        "label": "Vienna",
                        "value": "vienna"
                    }
                ],
                "token": "site",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_pulse": {
            "type": "ds.search",
            "options": {
                "query": "(index=demo_cisco_catalyst sourcetype=\"cisco:dnac:devicehealth\") OR (index=demo_mes production_rate_per_hour=*) OR (index=demo_cisco_meraki sourcetype=\"meraki:wirelessdevicespacketlossbydevice\")\n| rex field=Location \"(?i)(?<cat_site>vienna|berlin|atlanta)\"\n| rex field=network.name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval site=lower(coalesce(cat_site, mer_site, location))\n| stats avg(HealthScore) as campus dc(DeviceName) as devices dc(eval(if(Reachability!=\"Reachable\", DeviceName, null()))) as unreachable avg(oee_pct) as oee avg(downstream.lossPercentage) as wifi by site\n| where site IN (\"atlanta\", \"berlin\", \"vienna\")\n| eval score=round(campus * 10, 0)\n| eval status=case(unreachable > devices / 2 OR campus < 5, \"crit\", unreachable > 0 OR campus < 8 OR wifi > 2 OR oee < 70, \"warn\", isnotnull(campus), \"ok\")\n| eval detail=\"Campus \".round(campus, 1).\" · \".unreachable.\" of \".devices.\" devices unreachable · Wi-Fi loss \".round(wifi, 1).\" % · OEE \".round(oee, 0).\" %\"\n| append [search index=demo_thousendeyes sourcetype=\"thousendeyes:json\" thousandeyes.test.type=agent-to-agent earliest=-5m latest=now\n| stats avg(metric_name:network.loss) as loss avg(metric_name:network.latency) as latency by thousandeyes.agent.location thousandeyes.target.agent.location\n| rename thousandeyes.agent.location as site thousandeyes.target.agent.location as to\n| eval loss=round(loss, 2), latency_ms=round(latency * 1000, 0)\n| fields site to loss latency_ms]\n| append [| mstats avg(_value) as aborted WHERE index=demo_vmware_metrics metric_name=\"vmware.vm.gpu.llm.requests.aborted.pct\" location=\"frankfurt\" earliest=-5m latest=now\n| eval site=\"frankfurt\", score=round(100 - aborted, 0), detail=\"DC Frankfurt · GPU cluster · \".round(aborted, 1).\" % aborted LLM requests\"]\n| table site to score status loss latency_ms detail",
                "enableSmartSources": true,
                "queryParameters": {
                    "earliest": "-5m",
                    "latest": "now"
                },
                "refresh": "1m",
                "refreshType": "delay"
            },
            "name": "Site mesh (live)"
        },
        "ds_cat": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:dnac:devicehealth\"\n| rex field=Location \"(?i)(?<cat_site>vienna|berlin|atlanta)\"\n| eval site=lower(cat_site)\n| search site=\"$site$\"\n| stats latest(HealthScore) as health latest(CpuUtilization) as cpu latest(MemoryUtilization) as mem latest(Reachability) as reach by site DeviceName DeviceFamily",
                "enableSmartSources": true
            },
            "name": "Catalyst devices (latest)"
        },
        "ds_k_devices": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_cat",
                "query": "| stats dc(DeviceName) as Devices"
            }
        },
        "ds_k_health": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_cat",
                "query": "| stats avg(health) as Health | eval Health=round(Health, 1)"
            }
        },
        "ds_family": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_cat",
                "query": "| stats avg(health) as \"Health score\" avg(cpu) as \"CPU %\" avg(mem) as \"Memory %\" by DeviceFamily | eval \"Health score\"=round('Health score', 1), \"CPU %\"=round('CPU %', 1), \"Memory %\"=round('Memory %', 1)"
            }
        },
        "ds_family_health": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_family",
                "query": "| fields DeviceFamily \"Health score\""
            }
        },
        "ds_family_load": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_family",
                "query": "| fields DeviceFamily \"CPU %\" \"Memory %\""
            }
        },
        "ds_site_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_cat",
                "query": "| stats dc(DeviceName) as Devices avg(health) as \"Avg health\" avg(cpu) as \"Avg CPU %\" avg(mem) as \"Avg memory %\" count(eval(reach!=\"Reachable\")) as Unreachable by site\n| eval \"Avg health\"=round('Avg health', 1), \"Avg CPU %\"=round('Avg CPU %', 1), \"Avg memory %\"=round('Avg memory %', 1)\n| rename site as Site"
            }
        },
        "ds_adv": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:dnac:securityadvisory\"\n| stats first(description) as Description max(cvssScore) as CVSS first(status) as Status dc(DeviceName) as \"Affected devices\" by advisoryId advisorySeverity\n| rename advisoryId as \"Advisory ID\" advisorySeverity as Severity\n| sort - CVSS",
                "enableSmartSources": true
            },
            "name": "Security advisories"
        },
        "ds_k_adv": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_adv",
                "query": "| search Severity IN (\"CRITICAL\", \"HIGH\") | stats count as Advisories"
            }
        },
        "ds_adv_pie": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_adv",
                "query": "| stats count by Severity"
            }
        },
        "ds_mer": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_meraki sourcetype IN (\"meraki:assurancealerts\", \"meraki:wirelessdevicespacketlossbydevice\", \"meraki:devicesavailabilitieschangehistory\")\n| rex field=network.name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval site=lower(mer_site), network='network.name', new_status=mvindex('details.new{}.value', 0)\n| search site=\"$site$\"\n| stats count(eval(sourcetype=\"meraki:assurancealerts\")) as alerts count(eval(sourcetype=\"meraki:assurancealerts\" AND severity=\"critical\")) as critical avg(downstream.lossPercentage) as down_loss avg(upstream.lossPercentage) as up_loss dc(eval(if(new_status=\"offline\", 'device.serial', null()))) as offline by site network",
                "enableSmartSources": true
            },
            "name": "Meraki networks"
        },
        "ds_k_critical": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_mer",
                "query": "| stats sum(critical) as Critical"
            }
        },
        "ds_k_offline": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_mer",
                "query": "| stats sum(offline) as Offline"
            }
        },
        "ds_k_wifi": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_mer",
                "query": "| stats avg(down_loss) as Loss | eval Loss=round(Loss, 2)"
            }
        },
        "ds_mer_loss": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_mer",
                "query": "| where isnotnull(down_loss) | eval \"Downstream %\"=round(down_loss, 2), \"Upstream %\"=round(up_loss, 2) | sort - \"Downstream %\" | fields network \"Downstream %\" \"Upstream %\""
            }
        },
        "ds_mer_alerts": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_meraki sourcetype=\"meraki:assurancealerts\"\n| rex field=network.name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval site=lower(mer_site)\n| search site=\"$site$\"\n| chart count over alertType by site\n| addtotals fieldname=total\n| sort - total\n| head 10\n| fields - total",
                "enableSmartSources": true
            },
            "name": "Meraki alerts by type"
        },
        "ds_mer_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_mer",
                "query": "| where alerts > 0 OR offline > 0\n| sort - critical - alerts\n| eval \"Downstream loss %\"=round(down_loss, 2)\n| table site network alerts critical offline \"Downstream loss %\"\n| rename site as Site network as Network alerts as Alerts critical as Critical offline as \"Went offline\""
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_home",
                        "tokens": [],
                        "newTab": false
                    }
